document.addEventListener('DOMContentLoaded', () => {
  const form = document.querySelector('.wpcf7 form');
  if (!form) return;

  form.addEventListener('submit', function (e) {
    e.preventDefault();

    const fd = new FormData(form); // ➜ récupère toutes les valeurs automatiquement

    fetch('/wp-json/contact-form-7/v1/contact-forms/420/feedback', {
      method: 'POST',
      body: fd
    })
    .then(r => r.json())
    .then(d => {
      if (d.status === 'mail_sent') {
        alert('✅ Message envoyé !');
        form.reset();
      } else {
        alert('❌ Une erreur est survenue.');
        console.log(d);
      }
    })
    .catch(e => {
      console.error('Erreur CF7:', e);
      alert('❌ Erreur réseau');
    });
  });
});

