Podemos poner eso en un widget HTML en el footer en elementor :
<script>
  document.addEventListener('DOMContentLoaded', () => {
    const form = document.querySelector('.wpcf7 form');
    if (!form) return;

    form.addEventListener('submit', function (e) {
      e.preventDefault();

      const fd = new FormData(form);
      fd.set('your-name',     'Juan Pérez');
      fd.set('your-email',    'juan@email.com');
      fd.set('your-subject',  'Consulta Web');
      fd.set('your-message',  'Hola, quiero más información.');

      fetch('/wp-json/contact-form-7/v1/contact-forms/420/feedback', {
        method: 'POST',
        body: fd
      })
      .then(r => r.json())
      .then(d => {
        if (d.status === 'mail_sent') {
          alert('✅ Message envoyé !');
          form.reset();
        } else {
          alert('❌ Une erreur est survenue.');
        }
      })
      .catch(e => {
        console.error('Erreur CF7:', e);
        alert('❌ Erreur réseau');
      });
    });
  });
</script>

// 1) Récupère les champs obligatoires insérés dans le DOM par CF7
const form = document.querySelector('.wpcf7 form');      // ton formulaire
const fd   = new FormData(form);                         // récupère _wpcf7, _wpcf7_nonce, etc.

// 2) Ajoute/écrase les valeurs utilisateur
fd.set('your-name',     'Juan Pérez');
fd.set('your-email',    'juan@email.com');
fd.set('your-subject',  'Consulta Web');
fd.set('your-message',  'Hola, quiero más información.');

// 3) Envoie sans définir Content‑Type (le navigateur ajoute le boundary)
fetch('/wp-json/contact-form-7/v1/contact-forms/420/feedback', {
  method: 'POST',
  body: fd
})
.then(r => r.json())
.then(d => console.log('✅', d))
.catch(e => console.error('❌', e));

fetch("https://skycode.agency/wp-json/contact-form-7/v1/contact-forms/420/feedback", {
  method: "POST",
  headers: {
    "Content-Type": "application/json"
  },
  body: JSON.stringify({
    fields: {
      "your-name": "Juan Pérez",
      "your-email": "juan@email.com",
      "your-subject": "Consulta Web",
      "your-message": "Hola, quiero más información sobre su servicio."
    }
  })
})
.then(res => res.json())
.then(data => console.log("✅ Resultado:", data))
.catch(err => console.error("❌ Error:", err));
